descriptor.controllerScript:
self.onInit = function () {
  // ✅ Inject Tailwind CSS once
  if (!document.getElementById('tailwindcss')) {
    const script = document.createElement('script');
    script.src = 'https://cdn.tailwindcss.com';
    script.id = 'tailwindcss';
    script.onload = () => self.ctx.detectChanges();
    document.head.appendChild(script);
  }

  // Initialize variables
  const keys = [
    'cpu_usage',
    'ram_usage',
    'flash_usage',
    'device_temperature',
    'imei',
    'sim_iccid',
    'mac_address'
  ];

  keys.forEach(key => self[key] = (key.includes('usage') || key.includes('temperature')) ? 0 : '');

  // Handle new data
  self.onDataUpdated = function () {
    self.ctx.data.forEach(({ dataKey, data }) => {
      const key = dataKey.name;
      const value = data[data.length - 1]?.[1];
      if (value !== undefined && keys.includes(key)) {
        self[key] = isNaN(value) ? value : parseFloat(value).toFixed(2);
      }
    });
  };
};

